    this.loaderComponent.show();
    this.passwordActivationService
      .passwordActivation(this.dynamicKey.value!)
      .pipe(tap(() => this.loaderComponent.show()))
      .subscribe({
        next: (res) => {
          this.passwordActivationService.setDynamicKeyValidated(true);
          this.router.navigate(["/first-key-activation-completed"]);
        },
        error: (error) => {
          this.dynamicKey.reset();
