import { Component, ViewChild, inject } from "@angular/core";
import { FormControl } from "@angular/forms";
import { Router } from "@angular/router";
import { delay, tap } from "rxjs/operators";

import { BcAlertComponent } from "@bancolombia/design-system-web/bc-alert";
import { BcModalComponent } from "@bancolombia/design-system-web/bc-modal";
import { BcDialogService } from "@bancolombia/design-system-web/bc-services";

import { LoaderComponent } from "../../components/loader/loader.component";
import { PasswordActivationService } from "../../../core/services/password-activation.service";

@Component({
  selector: "app-dynamic-key-validation",
  templateUrl: "./dynamic-key-validation.component.html",
  styleUrls: ["./dynamic-key-validation.component.css"],
})
export class DynamicKeyValidationComponent {
  @ViewChild(BcModalComponent, { static: false }) BcModalEx!: BcModalComponent;
  @ViewChild("wrongKeyModal", { static: false }) wrongKeyModal!: BcModalComponent;
  @ViewChild("blockedKeyModal", { static: false }) blockedKeyModal!: BcModalComponent;
  @ViewChild("loaderComponent", { static: true }) loaderComponent!: LoaderComponent;

  private router = inject(Router);
  private dialogService = inject(BcDialogService);
  private passwordActivationService = inject(PasswordActivationService);

  numInputs: number = 6;
  dynamicKey = new FormControl("");
  errorCode = "";

  // Modal properties
  action = false;
  subTitle = "";
  typeIcon = "";
  closeModal = false;
  titleAlign = "";
  selectedValue = "";
  buttonAlignment = "horizontal";

  sendKey() {
    this.loaderComponent.show();
    this.passwordActivationService
      .passwordActivation(this.dynamicKey.value!)
      .pipe(
        tap(() => this.loaderComponent.show()),
        delay(5000) // Retrasar la suscripción por 5 segundos
