      this.handleErrorCode(this.errorCode);
    } else {
      this.openAlert("error", "Ha ocurrido un error inesperado");
    }
  }

  private handleErrorCode(code: string) {
    switch (code) {
      case "SFB002":
        this.openAlert(
          "error",
          "Alguno de los datos ingresados no es correcto. Por favor verifica e intenta nuevamente."
        );
        break;
      case "SFB003":
        this.showBlockedKeyModal();
        break;
      case "SFB004":
        this.openAlert(
          "error",
          "No es posible continuar con el proceso. Es necesario que te comuniques con nuestra sucursal telefonica."
        );
        break;
      case "SFB005":
        this.openAlert(
          "error",
          "El proceso no pudo ser completado. Contacta a nuestra sucursal telefónica."
        );
        break;
      default:
        this.openAlert("error", "Ha ocurrido un error inesperado");
        break;
    }
  }

  openAlert(type: string, text: string) {
    const dialogRef = this.dialogService.open(BcAlertComponent, {
      type: type,
      title: "Error",
      text: text,
      timeout: 10000,
    });

    dialogRef.onResult().subscribe(
      (closed) => {},
      (dismissed) => {
        alert("dismissed");
      },
      () => {}
    );
  }

  onPressButton(event: number) {
    if (event === 1 && this.errorCode === "SFB003") {
      this.passwordActivationService.interruptedTransaction();
      this.BcModalEx.shutDown();
    } else if (event === 0) {
      this.BcModalEx.shutDown();
    }
  }

  cancelProcess() {
    this.passwordActivationService.interruptedTransaction();
  }

  showSuccessModal() {
    this.BcModalEx.openModal();
  }

  showWrongKeyModal() {
    this.wrongKeyModal.openModal();
  }

  showBlockedKeyModal() {
    this.blockedKeyModal.openModal();
  }

  closeModalEvent(event: Event) {
    this.passwordActivationService.interruptedTransaction();
  }
}
